

const TODAY='2026-10-12',NOW='2026-10-12T10:30:00+07:00',KEY='lamie-orders-html-v5';
const STAGES=[['pending','Chờ xác nhận'],['confirmed','Đã xác nhận'],['preparing','Đang chuẩn bị'],['ready','Sẵn sàng giao'],['delivering','Đang giao'],['delivered','Đã giao']];
const LABEL=Object.fromEntries([...STAGES,['failed','Giao chưa thành công'],['cancelled','Đã hủy']]);
const GROUPS=[['late','Đang trễ','Cần xử lý trước'],['pending','Chưa giao','Trong hôm nay'],['upcoming','Sắp tới','Từ ngày mai'],['wait','Đã giao · Chờ tiền','Còn tiền cần thanh toán'],['done','Đã hoàn tất','Đã giao & đủ tiền']];
const NAV=[['overview','layout-dashboard','Tổng quan'],['orders','shopping-bag','Đơn hàng'],['calendar','calendar-days','Lịch giao']];
const THEMES=[['sage','Vườn sớm','#426753','#f7f8fa','#ffffff','#263833','#78857f','#e5eae6','#edf3ee'],['beige','Champagne','#8b7052','#f7f3ed','#fffcf7','#4c4338','#918577','#e9e0d4','#eee5d8'],['rose','Rose studio','#9a6571','#fbf6f7','#fffdfd','#533e45','#9b858d','#efdee4','#f7e9ed'],['blue','Blue hour','#516d91','#f3f6fa','#fff','#344252','#8090a3','#dfe6ef','#eaf0f8'],['olive','Olive atelier','#777748','#f7f7ef','#fffffa','#484a35','#93947d','#e4e5d5','#eeefdf'],['dark','Midnight','#638b79','#171e1c','#202925','#e5eee8','#9caea2','#35423a','#2d3d33']];
const fmt=n=>new Intl.NumberFormat('vi-VN').format(n)+'đ',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=d=>d.slice(8,10)+'/'+d.slice(5,7),plus=n=>{const d=new Date(TODAY+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};
function baseSeed(){const rows=[
[301,'Minh Anh','Bó hồng Juliet','pending',0,'11:00',850000,35000,0,null,'Chờ xác nhận màu giấy'],
[302,'Ngọc Hà','Giỏ hoa sinh nhật','confirmed',0,'12:30',1200000,40000,400000,null,''],
[303,'Bảo Ngân','Bó tulip trắng','preparing',0,'13:00',950000,35000,300000,35000,'Thiếu 5 cành tulip'],
[304,'Thu Linh','Bó hoa sắc thu','ready',0,'11:30',700000,40000,740000,40000,''],
[305,'Hoàng Nam','Giỏ hoa khai trương','delivering',0,'09:30',1500000,50000,500000,55000,''],
[306,'Mai Chi','Bó hồng Ohara','delivered',0,'08:30',600000,30000,300000,30000,''],
[307,'Khánh Vy','Box hoa pastel','delivered',-1,'16:00',1000000,40000,300000,40000,''],
[308,'Thanh Trúc','Bó cúc tana','delivered',0,'09:00',450000,30000,480000,null,''],
[309,'An Nhiên','Giỏ hoa garden','confirmed',1,'09:00',1800000,50000,500000,null,''],
[310,'Lê Phương','Bó hồng đỏ','pending',2,'14:00',800000,35000,0,null,''],
[311,'Tuấn Anh','Kệ hoa sự kiện','preparing',3,'10:00',2500000,70000,1000000,null,''],
[312,'Hải Yến','Bó hướng dương','failed',0,'10:00',650000,35000,300000,35000,''],
[313,'Kim Anh','Hoa chúc mừng','cancelled',0,'15:00',750000,35000,300000,null,''],
[314,'Trâm Anh','Bó hoa trắng','confirmed',6,'16:00',900000,40000,200000,null,''],
[315,'Ánh Dương','Giỏ hoa hồng','pending',7,'11:00',1000000,50000,0,null,'']
];return rows.map(([id,customer,product,stage,offset,time,price,ship,paid,actual,hold])=>({id,customer,product,stage,date:plus(offset),time,price,ship,paid,actual,hold,assignee:id===303?'Linh':id===311?'Vy':'Chưa phân công',prep:id===309?TODAY:plus(offset),checks:[false,false,false,false],refunded:0,deliveredAt:stage==='delivered'?plus(offset)+' '+time:null,completedAt:id===308?TODAY+' 09:00':null,history:[{at:'Dữ liệu mẫu',text:stage==='failed'?'Không liên hệ được người nhận':stage==='cancelled'?'Khách đổi kế hoạch · Cần hoàn cọc':LABEL[stage]}]}));}
let db;try{db=JSON.parse(localStorage.getItem(KEY))}catch{}if(!Array.isArray(db)||!db.length||!db[0].channel)db=seed();
let page='orders',view='list',range='7',group='',stageFilter='',search='',includeBacklog=true,selectedDate=TODAY,theme='sage';
let customFrom=TODAY,customTo=plus(6),modalOrder=null;
const get=id=>db.find(x=>x.id===id),total=o=>o.price+o.ship,customerDue=o=>Math.max(0,total(o)-o.paid),refundDue=o=>o.stage==='cancelled'?Math.max(0,o.paid-o.refunded):0;
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch{}}
function log(o,text){if(bucket(o)==='done'&&!o.completedAt)o.completedAt=TODAY+' 10:30';o.history.push({at:'12/10 · 10:30',text});save();render();}
function badge(txt,cls=''){return `<span class="badge ${cls}"><i class="dot"></i>${esc(txt)}</span>`}
function groupBadge(o){let g=GROUPS.find(x=>x[0]===bucket(o));return badge(g?g[1]:'Đã hủy',bucket(o))}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',3500)}
function go(p){page=p;render();window.scrollTo({top:0,behavior:'instant'})}
function heading(k,t,d,actions=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div><div class="row">${actions||'<button onclick="guide()">Quy trình & thiết kế</button>'}</div></div>`}
function scope(){let start=range==='tomorrow'?plus(1):range==='custom'?customFrom:TODAY,end=range==='all'?'9999':range==='today'?TODAY:range==='tomorrow'?plus(1):range==='3'?plus(2):range==='custom'?customTo:plus(6);return db.filter(o=>{let d=bucket(o)==='done'?o.completedAt?.slice(0,10)||o.date:o.date;return range==='all'||d>=start&&d<=end||includeBacklog&&o.date<start&&['late','wait'].includes(bucket(o))})}
function stats(rows,click=true){return `<div class="stats">${GROUPS.map(([g,n,d])=>`<button class="stat ${g} ${group===g&&page==='orders'?'selected':''}" ${click?`onclick="selectGroup('${g}')"`:''}><span>${n}</span><strong class="num">${rows.filter(o=>bucket(o)===g).length.toString().padStart(2,'0')}</strong><small>${d}</small></button>`).join('')}</div>`}
function selectGroup(g){group=page==='orders'&&group===g?'':g;page='orders';stageFilter='';view='list';render()}
function task(o){return `<div class="item"><div class="time">${o.time}<small>${date(o.date)}</small></div><div class="thumb">${o.product.startsWith('Bó')?'b':'g'}</div><div class="grow"><button class="orderlink" onclick="detail(${o.id})">LM-${o.id} · ${esc(o.customer)}</button><small>${esc(o.product)}</small></div><div class="badges">${badge(LABEL[o.stage],o.stage)}${o.hold?badge('Tạm dừng','wait'):''}</div><button onclick="next(${o.id})">${action(o)}</button></div>`}
function overview(){const today=db.filter(o=>o.date===TODAY&&o.stage!=='cancelled'),del=today.filter(o=>o.stage==='delivered').length,priority=db.filter(o=>bucket(o)==='late'||o.stage==='pending'&&o.date===TODAY).slice(0,3),prep=db.filter(o=>o.prep===TODAY&&['confirmed','preparing'].includes(o.stage));return heading('TỔNG QUAN / NHỊP LÀM VIỆC','Một ngày gọn gàng, từng đơn trọn vẹn.','Nắm tiến độ xác nhận, chuẩn bị, giao hàng và tiền cần nhận.')+`<div class="hero"><div><small>THỨ HAI, 12 THÁNG 10</small><h2>Hôm nay, Lamie có ${today.length} đơn giao.</h2><p>${today.filter(o=>o.stage==='pending').length} đơn cần xác nhận · ${prep.length} đơn cần chuẩn bị trong ngày.<br>Mọi tiến trình đều bắt đầu từ một đơn đã rõ thông tin.</p><button onclick="range='today';group='';stageFilter='';go('orders')">Mở danh sách hôm nay →</button></div><div><small>TIẾN ĐỘ GIAO HÔM NAY</small><div class="metric">${del} <small>/ ${today.length} đơn đã giao</small></div><div class="pipe"><span style="width:${100*del/today.length}%;background:#d9e8bf"></span><span style="flex:1"></span></div><div class="legend"><span>● ${today.length-del} đơn chưa giao</span><span>● ${today.filter(o=>bucket(o)==='done').length} đơn hoàn tất</span></div></div></div>`+stats(db.filter(o=>o.date<=TODAY||o.date<=plus(6)))+`<div class="card pad"><div class="sectionhead"><div><h2>Tiến trình xử lý</h2><p>Đơn giao hôm nay · bấm từng bước để xem việc cần làm</p></div><button onclick="view='board';range='today';stageFilter='';group='';go('orders')">Bảng chuẩn bị →</button></div><div class="flowline">${STAGES.map(([s,n])=>`<button class="flowstep" onclick="stageFilter='${s}';range='today';group='';view='list';go('orders')"><small>${n}</small><strong>${today.filter(o=>o.stage===s).length}</strong></button>`).join('')}</div></div><div class="grid2"><section class="card pad"><div class="sectionhead"><div><h2>Cần bạn xử lý trước</h2><p>Đơn quá giờ hẹn và đơn đang chờ xác nhận</p></div>${badge(priority.length+' việc','late')}</div>${priority.map(task).join('')}</section><section class="card pad"><div class="sectionhead"><div><h2>Chuẩn bị hôm nay</h2><p>Bao gồm đơn giao ngày mai, cần làm từ hôm nay</p></div></div>${prep.map(o=>`<div class="item"><div class="grow"><button class="orderlink" onclick="detail(${o.id})">LM-${o.id} · ${esc(o.product)}</button><small>Giao ${date(o.date)} · ${o.time} / ${esc(o.assignee)}</small></div>${o.hold?badge('Thiếu hoa','wait'):badge('Cần chuẩn bị','confirmed')}</div>`).join('')}</section></div><div class="grid2"><section class="card pad"><h2>Lượng đơn những ngày tới</h2>${[1,2,3,4,5,6].map(n=>{let count=db.filter(o=>o.date===plus(n)&&o.stage!=='cancelled').length;return `<div class="chartrow"><span>${date(plus(n))}</span><div><i style="width:${count*45}%"></i></div><b>${count}</b></div>`}).join('')}</section><section class="card pad"><span class="eyebrow">NGUYÊN TẮC XUYÊN SUỐT</span><h2 style="margin-top:12px">Đã giao chưa có nghĩa là hoàn tất.</h2><p class="bottomnote">Tiến trình làm hoa, vận chuyển và trạng thái thanh toán được nhìn độc lập trên mỗi đơn.</p><div class="notice">✓ Đã giao thành công<br>✓ Đã thanh toán đủ<br><strong>→ Tự động hoàn tất</strong></div><button onclick="selectGroup('wait')">Kiểm tra tiền còn chờ →</button></section></div>`}
function orders(){return heading('ĐƠN HÀNG / ĐIỀU PHỐI','Mọi đơn hàng, rõ trong một cái nhìn.','Người đặt, kênh đặt, cách nhận, tiền còn lại và lời nhắn — ngay trên từng dòng.', '<button onclick="guide()">Hướng dẫn</button><button class="primary" onclick="openCreate()">＋ Tạo đơn hàng</button>')+`<div class="tabs"><button class="${view==='list'?'active':''}" onclick="view='list';render()">Danh sách đơn</button><button class="${view==='board'?'active':''}" onclick="view='board';render()">Bảng xác nhận & chuẩn bị</button></div><div class="toolbar"><div class="seg">${[['all','Tất cả'],['today','Hôm nay'],['tomorrow','Ngày mai'],['3','3 ngày'],['7','7 ngày'],['custom','Tùy chọn']].map(([v,l])=>`<button class="${range===v?'active':''}" onclick="range='${v}';render()">${l}</button>`).join('')}</div><input aria-label="Tìm đơn" class="search" placeholder="Tìm mã đơn, người đặt, số điện thoại…" value="${esc(search)}" oninput="search=this.value;refreshOrders()"></div>${range==='custom'?`<div class="row" style="max-width:420px;margin-bottom:12px"><input aria-label="Từ ngày" type="date" value="${customFrom}" onchange="customFrom=this.value;render()"><span>→</span><input aria-label="Đến ngày" type="date" min="${customFrom}" value="${customTo}" onchange="customTo=this.value;render()"></div>`:''}<div class="range-note"><label class="check"><input type="checkbox" ${includeBacklog?'checked':''} onchange="includeBacklog=this.checked;render()">Kèm đơn trễ / chờ tiền từ trước kỳ</label><span>7 ngày = 12–18/10 · Hoàn tất lọc theo ngày hoàn tất</span></div>`+stats(scope())+`<div class="stages"><button class="${!stageFilter?'active':''}" onclick="stageFilter='';render()">Mọi tiến trình</button>${[...STAGES,['failed','Giao lỗi'],['cancelled','Đã hủy']].map(([s,n])=>`<button class="${stageFilter===s?'active':''}" onclick="stageFilter='${s}';render()">${n}</button>`).join('')}</div><div class="quickfilters"><select aria-label="Lọc thanh toán" onchange="payFilter=this.value;refreshOrders()"><option value="">Mọi thanh toán</option><option value="unpaid" ${payFilter==='unpaid'?'selected':''}>Chưa thanh toán đủ</option><option value="paid" ${payFilter==='paid'?'selected':''}>Đã thanh toán</option></select><select aria-label="Lọc cách nhận" onchange="fulfillFilter=this.value;refreshOrders()"><option value="">Mọi cách nhận</option>${Object.entries(FULFILL).map(([k,v])=>`<option value="${k}" ${fulfillFilter===k?'selected':''}>${v}</option>`).join('')}</select><span class="muted">Bấm biểu tượng thiệp / banner để xem nội dung</span></div><div id="orders-result">${orderResult()}</div>`}
function refreshOrders(){document.getElementById('orders-result').innerHTML=orderResult()}
function calendar(){let rows=db.filter(o=>o.date===selectedDate&&o.stage!=='cancelled').sort((a,b)=>a.time.localeCompare(b.time));return heading('LỊCH GIAO / LỊCH CHUẨN BỊ','Biết ngày giao. Chủ động ngày làm.','Ngày chuẩn bị được theo dõi riêng để đơn giao sáng mai có thể hoàn thiện từ hôm nay.')+`<div class="week">${Array.from({length:7},(_,n)=>plus(n)).map(d=>{let r=db.filter(o=>o.date===d&&o.stage!=='cancelled');return `<button class="day ${selectedDate===d?'active':''}" onclick="selectedDate='${d}';render()"><small>${d===TODAY?'HÔM NAY':d===plus(1)?'NGÀY MAI':'THÁNG 10'}</small><strong>${d.slice(8)}</strong><small>${r.length} đơn giao</small><div class="dots">${r.slice(0,6).map(o=>`<i style="opacity:${o.stage==='delivered'?.3:1}"></i>`).join('')}</div></button>`}).join('')}</div><div class="grid2"><section class="card pad"><div class="sectionhead"><div><h2>Lịch giao ${date(selectedDate)}</h2><p>Tiến trình đơn hiển thị ngay cạnh giờ hẹn</p></div>${badge(rows.length+' đơn')}</div>${rows.map(task).join('')||'<div class="empty">Chưa có đơn giao</div>'}</section><section class="card pad"><div class="sectionhead"><div><h2>Cần chuẩn bị ${date(selectedDate)}</h2><p>Độc lập với ngày giao hàng</p></div></div>${db.filter(o=>o.prep===selectedDate&&['confirmed','preparing'].includes(o.stage)).map(o=>`<div class="item"><div class="grow"><button class="orderlink" onclick="detail(${o.id})">LM-${o.id} · ${esc(o.product)}</button><small>Giao ${date(o.date)} · ${o.time}</small><small>${esc(o.assignee)}</small></div>${badge(LABEL[o.stage],o.stage)}</div>`).join('')||'<div class="empty">Không có việc chuẩn bị</div>'}<div class="notice">Đơn LM-309 giao 09:00 ngày mai, được đặt lịch chuẩn bị hôm nay.</div></section></div>`}
function themePage(){return heading('GIAO DIỆN / CÁ NHÂN HÓA','Chọn không gian làm việc.','Chủ đề thay đổi đồng bộ nền, thẻ, chữ và điểm nhấn.')+`<div class="theme-grid">${THEMES.map(([id,n,b,bg,c])=>`<button onclick="setTheme('${id}')"><div class="swatch" style="background:${bg}"><span style="background:${b}"></span></div>${n} ${theme===id?'✓':''}</button>`).join('')}</div><div class="notice">Icon Lucide Animated chỉ dùng trên sidebar và chỉ chuyển động khi tương tác. Tôn trọng tùy chọn giảm chuyển động của thiết bị.</div>`}
function setTheme(id){theme=id;let t=THEMES.find(t=>t[0]===id);['brand','bg','card','ink','muted','line','soft'].forEach((k,i)=>document.documentElement.style.setProperty('--'+k,t[i+2]));document.documentElement.style.setProperty('--aside',t[4]);render()}
function modal(title,body,kicker='LAMIE / QUY TRÌNH'){document.getElementById('modal-title').textContent=title;document.getElementById('modal-kicker').textContent=kicker;document.getElementById('modal-body').innerHTML=body;const d=document.getElementById('modal');if(!d.open)d.showModal();document.getElementById('modal-body').scrollTop=0}
function closeModal(){document.getElementById('modal').close();modalOrder=null}
function form(title,body,submit,label='Lưu thay đổi'){modal(title,`<form onsubmit="event.preventDefault();${submit}">${body}<p id="form-error" role="alert"></p><div class="modalfoot"><button type="button" onclick="closeModal()">Để sau</button><button class="primary" type="submit">${label}</button></div></form>`)}
const err=t=>{document.getElementById('form-error').textContent=t;return false},val=id=>document.getElementById(id).value,checked=id=>document.getElementById(id).checked;
function prepDialog(id){let o=get(id);form('Phân công & bắt đầu chuẩn bị',`<div class="notice">LM-${id} · ${esc(o.product)}<br>Ngày chuẩn bị có thể sớm hơn ngày giao.</div><label class="fieldlabel">Người phụ trách</label><select id="assignee"><option>Linh</option><option>Vy</option><option>Chủ tiệm</option></select><label class="fieldlabel">Ngày chuẩn bị</label><input type="date" id="prepdate" value="${o.prep}" max="${o.date}" required><div class="checks"><label><input type="checkbox" id="materials" required>Đã kiểm tra hoa, giấy gói và phụ kiện cần dùng</label></div>`,`doPrep(${id})`,'Bắt đầu chuẩn bị')}
function doPrep(id){let o=get(id);if(o.stage!=='confirmed'||o.hold)return err('Đơn cần được xác nhận và không tạm dừng.');if(!checked('materials'))return err('Cần kiểm tra nguyên liệu.');if(!val('prepdate')||val('prepdate')>o.date)return err('Ngày chuẩn bị không được sau ngày giao.');o.stage='preparing';o.assignee=val('assignee');o.prep=val('prepdate');log(o,'Bắt đầu chuẩn bị · '+o.assignee);detail(id)}
const CHECKS=['Đúng mẫu hoa, tone màu và số lượng','Hoa đạt chất lượng, bó / giỏ chắc chắn','Thiệp và lời nhắn chính xác','Đóng gói, bảo quản và ảnh thành phẩm đã kiểm tra'];
function checklistDialog(id){let o=get(id);form('Checklist trước khi sẵn sàng giao',`<div class="notice">LM-${id} · ${esc(o.product)} · ${esc(o.assignee)}</div><div class="checks">${CHECKS.map((t,i)=>`<label><input type="checkbox" id="check${i}" ${o.checks[i]?'checked':''}>${t}</label>`).join('')}</div><small>Đánh dấu từng mục rồi lưu tiến độ, hoặc hoàn thành đủ 4 mục để chuyển “Sẵn sàng giao”.</small><div style="margin-top:15px"><button type="button" onclick="saveChecks(${id},false)">Lưu tiến độ chuẩn bị</button></div>`,`saveChecks(${id},true)`,'Đánh dấu sẵn sàng giao')}
function saveChecks(id,advance){let o=get(id);if(o.stage!=='preparing'||o.hold)return err('Đơn chưa thể tiếp tục.');const checks=[0,1,2,3].map(i=>checked('check'+i));if(advance&&!checks.every(Boolean))return err('Cần hoàn thành cả 4 mục trước khi sẵn sàng giao.');o.checks=checks;if(advance)o.stage='ready';log(o,advance?'Hoàn thành kiểm tra · Sẵn sàng giao':'Lưu checklist '+checks.filter(Boolean).length+'/4');detail(id)}
function shippingFields(o){return `<label class="fieldlabel">Phí ship thực tế (đ)</label><input type="number" min="0" step="1" id="shipcost" placeholder="Chưa biết — có thể để trống" value="${o.actual??''}"><small>Tính khách ${fmt(o.ship)} · 0đ là miễn phí, để trống là chưa chốt.</small>`}
function parseCost(){let v=val('shipcost');return v===''?null:Number(v)}
function shipDialog(id){let o=get(id);form('Cập nhật nhanh phí ship',`<div class="notice">LM-${id} · Sửa phí ngay tại đây, không cần vào sửa toàn bộ đơn.</div>${shippingFields(o)}`,`saveShip(${id})`)}
function holdDialog(id){let o=get(id);form('Tạm dừng tại bước hiện tại',`<p class="muted">Giữ nguyên “${LABEL[o.stage]}”, thêm lý do để người phụ trách biết việc cần xử lý.</p><label class="fieldlabel">Lý do</label><textarea id="holdreason" required placeholder="Chờ khách phản hồi, chờ cọc, thiếu hoa…">${esc(o.hold)}</textarea>`,`doHold(${id})`,'Lưu lý do')}
function doHold(id){let o=get(id),reason=val('holdreason').trim();if(!reason)return err('Vui lòng nhập lý do.');o.hold=reason;log(o,'Tạm dừng · '+reason);detail(id)}
function resume(id){let o=get(id);o.hold='';log(o,'Đã xử lý tạm dừng · tiếp tục bước '+LABEL[o.stage]);detail(id)}
function failDialog(id){form('Ghi nhận giao chưa thành công','<label class="fieldlabel">Lý do</label><textarea id="failreason" required placeholder="Không liên hệ được người nhận…"></textarea>',`doFail(${id})`,'Ghi nhận sự cố')}
function doFail(id){let o=get(id);if(o.stage!=='delivering')return err('Đơn không ở bước đang giao.');if(!val('failreason').trim())return err('Cần nhập lý do.');o.stage='failed';log(o,'Giao chưa thành công · '+val('failreason').trim());detail(id)}
function retryDialog(id){let o=get(id);form('Chốt lịch và chuẩn bị giao lại',`<div class="notice">Đơn quay về “Sẵn sàng giao”. Kiểm tra lại chất lượng hoa, người nhận và lịch hẹn trước khi bàn giao.</div><label class="fieldlabel">Ngày giao lại</label><input type="date" min="${TODAY}" id="retrydate" value="${TODAY}" required><label class="fieldlabel">Giờ hẹn mới</label><input type="time" id="retrytime" value="14:00" required><div class="checks"><label><input id="retrycheck" type="checkbox" required>Đã kiểm tra hoa và xác nhận lại với người nhận</label></div>`,`doRetry(${id})`,'Sẵn sàng giao lại')}
function doRetry(id){let o=get(id);if(o.stage!=='failed'||!checked('retrycheck'))return err('Cần xác nhận trước khi giao lại.');if(val('retrydate')+'T'+val('retrytime')+':00+07:00'<NOW)return err('Hẹn lại từ thời điểm mô phỏng trở đi.');o.date=val('retrydate');o.time=val('retrytime');o.stage='ready';log(o,'Hẹn giao lại '+date(o.date)+' '+o.time);detail(id)}
function doCancel(id){let o=get(id);if(!['pending','confirmed','preparing','ready'].includes(o.stage))return err('Chỉ hủy trực tiếp trước khi bàn giao.');if(!val('cancelreason').trim())return err('Cần nhập lý do hủy.');o.stage='cancelled';o.hold='';log(o,'Hủy đơn · '+val('cancelreason').trim());detail(id)}

const FULFILL={pickup:'Ghé lấy',city:'Ship nội thành',province:'Ship tỉnh'};
let payFilter='',fulfillFilter='',selectedOrder=301,detailTab='info',draft=null;
const noteSVG='<svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/></svg>';
function seed(){return baseSeed().map((o,i)=>({...o,ship:i%5===3?0:o.ship,actual:i%5===3?0:o.actual,paid:i%5===3?Math.min(o.paid,o.price):o.paid,channel:['Facebook','Instagram','Zalo','Tại tiệm','Website'][i%5],buyerPhone:'090 000 '+String(o.id).padStart(4,'0'),fulfillment:i%5===3?'pickup':i%5===0?'province':'city',recipient:i===0||i===9?'':['Hồng An','Mai Hương','Bảo Ngọc'][i%3],recipientPhone:i===0||i===9?'':'091 000 '+String(o.id).padStart(4,'0'),address:i===0||i===9?'':i%5===0?'24 Đường Mẫu, phường Bình An, Đồng Nai':'12 Đường Mẫu, phường Bến Thành, TP.HCM',extraType:i%4===0?'Thiệp':i%4===1?'Banner':'Không',extra:i%4===0?'Chúc em một ngày thật dịu dàng.\nLuôn vui và luôn được yêu thương!':i%4===1?'CHÚC MỪNG KHAI TRƯƠNG\nHồng phát • Vạn sự như ý':'',note:i===2?'Nếu thiếu tulip trắng, liên hệ người đặt trước khi đổi hoa.':'',qty:1,unitPrice:o.price,createdAt:'12/10/2026 · 08:00'}));}
function stageText(o){return o.fulfillment==='pickup'?({ready:'Sẵn sàng nhận',delivered:'Đã nhận tại tiệm'}[o.stage]||LABEL[o.stage]):LABEL[o.stage]}
function bucket(o){if(o.stage==='cancelled')return 'cancelled';if(o.stage==='delivered')return customerDue(o)===0?'done':'wait';if(o.date+'T'+o.time+':00+07:00'<NOW)return 'late';return o.date===TODAY?'pending':'upcoming'}
function moneyState(o){return o.stage==='cancelled'?(refundDue(o)?'Cần hoàn '+fmt(refundDue(o)):'Đã xử lý tiền'):customerDue(o)?'Còn '+fmt(customerDue(o)):'Đã thanh toán'}
function paymentUI(o){if(o.stage==='cancelled')return badge(refundDue(o)?'Cần hoàn tiền':'Đã xử lý tiền','cancelled')+(refundDue(o)?`<small class="due">${fmt(refundDue(o))}</small>`:'');return customerDue(o)>0?`${badge('Chưa thanh toán đủ','wait')}<small class="due">Còn <b>${fmt(customerDue(o))}</b></small>`:badge('Đã thanh toán','done')}
function filtered(){return scope().filter(o=>(!group||bucket(o)===group)&&(!stageFilter||o.stage===stageFilter)&&(!payFilter||o.stage!=='cancelled'&&(payFilter==='paid'?customerDue(o)===0:customerDue(o)>0))&&(!fulfillFilter||o.fulfillment===fulfillFilter)&&(!search||(`${o.id} ${o.customer} ${o.product} ${o.buyerPhone} ${o.channel} ${o.recipient}`).toLocaleLowerCase('vi').includes(search.toLocaleLowerCase('vi')))).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))}
function extraButton(o){return o.extra?`<span class="extra-wrap"><button class="extra-button" type="button" aria-label="Xem nội dung ${esc(o.extraType)} của đơn LM-${o.id}" aria-haspopup="dialog" onclick="showExtra(${o.id})">${noteSVG}<span>${esc(o.extraType)}</span></button><span class="extra-hover" role="tooltip"><b>${esc(o.extraType)} · LM-${o.id}</b><span>${esc(o.extra)}</span></span></span>`:'<span class="muted">Không kèm</span>'}
function showExtra(id){const o=get(id);modal(`${o.extraType} · LM-${id}`,`<div class="message-paper"><small>NỘI DUNG ĐÃ CHỐT VỚI NGƯỜI ĐẶT</small><div>${esc(o.extra)}</div></div><p class="bottomnote">Người đặt: ${esc(o.customer)} · ${esc(o.channel)}</p><div class="modalfoot"><button onclick="detail(${id})">Xem tóm tắt</button><button class="primary" onclick="closeModal()">Đóng</button></div>`,'NỘI DUNG ĐÍNH KÈM')}
function action(o){if(o.stage==='cancelled')return refundDue(o)?'Hoàn tiền':'Xem tóm tắt';if(o.hold)return 'Xử lý tạm dừng';return {pending:'Xác nhận đơn',confirmed:'Bắt đầu chuẩn bị',preparing:'Checklist chuẩn bị',ready:o.fulfillment==='pickup'?'Khách đã nhận hoa':'Bàn giao shipper',delivering:'Xác nhận đã giao',failed:'Xử lý giao lại',delivered:bucket(o)==='done'?'Xem tóm tắt':'Đánh dấu đã thanh toán'}[o.stage]}
function next(id){let o=get(id);if(o.hold)return detail(id);switch(o.stage){case 'pending':return confirmDialog(id);case 'confirmed':return prepDialog(id);case 'preparing':return checklistDialog(id);case 'ready':return o.fulfillment==='pickup'?deliveredDialog(id):dispatchDialog(id);case 'delivering':return deliveredDialog(id);case 'failed':return retryDialog(id);case 'delivered':return customerDue(o)?payDialog(id):detail(id);case 'cancelled':return refundDue(o)?payDialog(id,'refund'):detail(id)}}
function orderResult(){let rows=filtered();if(view==='board')return boardResult(rows);let days=[...new Set(rows.map(o=>o.date))];return `<div class="list-caption"><span><b>${rows.length}</b> đơn trong danh sách</span><span>Tóm tắt: thao tác nhanh · Chi tiết: xem toàn bộ</span></div><div class="card rich-grid"><table class="ordertable rich-table"><thead><tr><th>ĐƠN / LỊCH HẸN</th><th>NGƯỜI ĐẶT / KÊNH</th><th>NHẬN HÀNG</th><th>TIẾN TRÌNH</th><th>THANH TOÁN</th><th>NỘI DUNG THÊM</th><th>THAO TÁC</th></tr></thead><tbody>${days.map(d=>`<tr class="dategroup"><td colspan="7">${d===TODAY?'HÔM NAY':d===plus(1)?'NGÀY MAI':'LỊCH HẸN'} · ${date(d)}/2026 <span>${rows.filter(o=>o.date===d).length} đơn</span></td></tr>${rows.filter(o=>o.date===d).map(o=>`<tr class="data-row"><td data-label="Đơn / lịch hẹn"><button class="orderlink" onclick="openDetail(${o.id})">LM-${o.id}</button><strong class="order-time">${o.time}</strong><small>${esc(o.product)}</small></td><td data-label="Người đặt / kênh"><b>${esc(o.customer)}</b><small>${esc(o.buyerPhone)}</small><span class="channel">${esc(o.channel)}</span></td><td data-label="Nhận hàng">${badge(FULFILL[o.fulfillment],'upcoming')}<small>${o.fulfillment==='pickup'?'Tại tiệm Lamie':o.recipient?'Nhận: '+esc(o.recipient):'<span class="missing">Chưa có người nhận</span>'}</small>${o.fulfillment!=='pickup'?`<button class="text shipping-mini" onclick="shipDialog(${o.id})">Ship thực tế: ${o.actual===null?'chưa chốt':fmt(o.actual)} ↗</button>`:''}</td><td data-label="Tiến trình">${badge(stageText(o),o.stage)}<small>${groupBadge(o)}</small>${o.hold?`<small class="missing">Tạm dừng: ${esc(o.hold)}</small>`:''}</td><td data-label="Thanh toán"><b class="total-small">${fmt(total(o))}</b>${paymentUI(o)}</td><td data-label="Nội dung thêm">${extraButton(o)}</td><td data-label="Thao tác"><div class="row-actions"><button class="summary-btn" onclick="detail(${o.id})">Xem tóm tắt</button><button class="text" onclick="openDetail(${o.id})">Xem chi tiết →</button></div></td></tr>`).join('')}`).join('')||'<tr><td colspan="7" class="empty">Không có đơn khớp bộ lọc.</td></tr>'}</tbody></table></div>`}
function boardResult(rows){return `<div class="notice">Theo dõi 4 bước trước giao. Mỗi thẻ có người đặt, cách nhận và tiền còn thiếu.</div><div class="board">${STAGES.slice(0,4).map(([s,n])=>`<section class="column"><div class="column-head"><b>${n}</b>${rows.filter(o=>o.stage===s).length}</div>${rows.filter(o=>o.stage===s).map(o=>`<article class="ticket"><div class="row between"><b>LM-${o.id}</b><small>${date(o.date)} · ${o.time}</small></div><h3>${esc(o.product)}</h3><p>${esc(o.customer)} · ${esc(o.channel)}</p><div class="badges">${badge(FULFILL[o.fulfillment])}${groupBadge(o)}</div><div style="margin:12px 0">${paymentUI(o)}</div>${extraButton(o)}${o.hold?`<div class="notice warn">${esc(o.hold)}</div>`:''}<button onclick="detail(${o.id})">Xem tóm tắt</button><button class="text" onclick="openDetail(${o.id})">Xem chi tiết →</button></article>`).join('')||'<div class="empty">Không có đơn</div>'}</section>`).join('')}</div>`}
function render(){let navPage=['detail','create'].includes(page)?'orders':page;document.getElementById('nav').innerHTML=`<button class="create primary" onclick="openCreate()"><i data-lucide="plus"></i>Tạo đơn hàng</button>`+NAV.map(([p,i,n])=>`<button class="navitem ${navPage===p?'active':''}" ${navPage===p?'aria-current="page"':''} onclick="go('${p}')"><i data-lucide="${i}"></i>${n}${p==='orders'?'<em>'+db.filter(o=>o.stage==='pending').length+'</em>':''}</button>`).join('');document.getElementById('crumb').textContent=page==='detail'?'Đơn hàng / LM-'+selectedOrder:page==='create'?'Đơn hàng / Tạo mới':NAV.find(n=>n[0]===page)?.[2]||'Chủ đề giao diện';document.getElementById('content').innerHTML=({overview,orders,calendar,themes:themePage,detail:detailPage,create:createPage}[page])()+`<div class="footer"><span>Lamie • Mockup HTML tương tác / dữ liệu giả lập</span><span><button class="text" onclick="guide()">Các thay đổi</button> · <button class="text" onclick="go('themes')">Chủ đề</button> · <button class="text" onclick="resetDialog()">Khôi phục mẫu</button></span></div>`;window.LamieMotion?.enhance(document.getElementById('sidebar'));if(page==='create')updateDraftTotals()}
function detail(id){const o=get(id);modalOrder=id;modal(`LM-${id} · ${o.customer}`,`<div class="summary-top"><div>${badge(stageText(o),o.stage)} ${groupBadge(o)}</div><div>${paymentUI(o)}</div></div><div class="summary-product"><div class="thumb">L</div><div><h2>${esc(o.product)}</h2><small>${o.qty} sản phẩm · Tổng đơn ${fmt(total(o))}</small></div><b>${o.time}<small>${date(o.date)}/2026</small></b></div><div class="summary-facts"><div><small>NGƯỜI ĐẶT</small><b>${esc(o.customer)}</b><span>${esc(o.buyerPhone)} · ${esc(o.channel)}</span></div><div><small>CÁCH NHẬN</small><b>${FULFILL[o.fulfillment]}</b><span>${o.fulfillment==='pickup'?'Nhận tại tiệm Lamie':o.recipient?esc(o.recipient)+' · '+esc(o.recipientPhone):'Chưa có thông tin người nhận'}</span></div><div><small>NGƯỜI PHỤ TRÁCH</small><b>${esc(o.assignee)}</b><span>Chuẩn bị ${date(o.prep)}</span></div><div><small>NỘI DUNG THÊM</small>${extraButton(o)}<span>${o.note?esc(o.note):'Không có ghi chú nội bộ'}</span></div></div>${o.hold?`<div class="notice warn">Tạm dừng: ${esc(o.hold)} <button class="text" onclick="resume(${id})">Đã xử lý → tiếp tục</button></div>`:''}${o.fulfillment!=='pickup'&&!receiverReady(o)?`<div class="notice warn">Có thể xác nhận và chuẩn bị trước. Bổ sung người nhận trước khi bàn giao. <button class="text" onclick="recipientDialog(${id})">Bổ sung ngay</button></div>`:''}<div class="summary-actions"><small>THAO TÁC NHANH</small><div class="row wrap"><button class="primary" onclick="next(${id})">${action(o)}</button>${o.stage!=='cancelled'&&customerDue(o)>0&&o.stage!=='delivered'?`<button onclick="payDialog(${id})">Đánh dấu đã thanh toán</button>`:''}${o.fulfillment!=='pickup'?`<button onclick="shipDialog(${id})">Ship: ${o.actual===null?'cập nhật':fmt(o.actual)}</button>`:''}</div></div><div class="modalfoot"><button onclick="closeModal()">Đóng</button><button onclick="openDetail(${id})">Xem chi tiết đầy đủ →</button></div>`,'TÓM TẮT / THAO TÁC NHANH')}
function openDetail(id){closeModal();selectedOrder=id;detailTab='info';go('detail')}
function receiverReady(o){return !!(o.recipient?.trim()&&o.recipientPhone?.trim()&&o.address?.trim())}
function detailPage(){let o=get(selectedOrder),idx=STAGES.findIndex(([s])=>s===o.stage);if(!o)return '<div class="empty">Không tìm thấy đơn.</div>';return `<button class="text back-link" onclick="go('orders')">← Quay lại danh sách đơn</button>`+heading('ĐƠN HÀNG / CHI TIẾT',`LM-${o.id}`,`${esc(o.customer)} · ${esc(o.channel)} · Tạo ${o.createdAt}`,`<button onclick="detail(${o.id})">Xem tóm tắt</button><button class="primary" onclick="next(${o.id})">${action(o)}</button>`)+`<div class="detail-statebar"><div class="row wrap">${badge(stageText(o),o.stage)}${groupBadge(o)}${o.hold?badge('Tạm dừng','wait'):''}</div>${paymentUI(o)}</div><div class="card pad"><div class="steps page-steps">${STAGES.map(([s,n],i)=>`<div class="step ${i<=idx?'passed':''} ${i===idx?'current':''}">${i+1}. ${o.fulfillment==='pickup'&&s==='ready'?'Sẵn sàng nhận':o.fulfillment==='pickup'&&s==='delivering'?'Không áp dụng':o.fulfillment==='pickup'&&s==='delivered'?'Đã nhận tại tiệm':n}</div>`).join('')}</div></div><div class="detail-layout"><div class="detail-main"><section class="card pad"><div class="sectionhead"><h2>Người đặt & nguồn đơn</h2><span class="channel">${esc(o.channel)}</span></div><div class="info-grid"><div><small>Người đặt</small><strong>${esc(o.customer)}</strong></div><div><small>Số điện thoại</small><strong>${esc(o.buyerPhone)}</strong></div></div></section><section class="card pad"><div class="sectionhead"><h2>Thông tin nhận hàng</h2><button onclick="recipientDialog(${o.id})">${o.recipient?'Cập nhật':'Bổ sung thông tin'}</button></div><div class="info-grid"><div><small>Loại nhận hàng</small><strong>${FULFILL[o.fulfillment]}</strong></div><div><small>Ngày & giờ hẹn</small><strong>${date(o.date)}/2026 · ${o.time}</strong></div><div><small>Người nhận</small><strong>${esc(o.recipient)||'Chưa cung cấp'}</strong></div><div><small>Số điện thoại người nhận</small><strong>${esc(o.recipientPhone)||'Chưa cung cấp'}</strong></div><div class="span2"><small>${o.fulfillment==='pickup'?'Điểm nhận':'Địa chỉ nhận'}</small><strong>${o.fulfillment==='pickup'?'Tại tiệm Lamie':esc(o.address)||'Chưa cung cấp'}</strong></div></div>${o.fulfillment!=='pickup'&&!receiverReady(o)?'<div class="notice warn">Thông tin còn trống được phép bổ sung sau khi tạo đơn, trước khi bàn giao.</div>':''}</section><section class="card pad"><div class="sectionhead"><h2>Sản phẩm</h2><small>${o.qty} sản phẩm</small></div><div class="line-product"><div class="thumb">L</div><div class="grow"><h3>${esc(o.product)}</h3><small>Đơn giá ${fmt(o.unitPrice)} × ${o.qty}</small></div><strong>${fmt(o.price)}</strong></div></section><section class="card pad"><div class="sectionhead"><h2>Thiệp, banner & ghi chú</h2>${badge(o.extraType)}</div>${o.extra?`<div class="message-paper"><div>${esc(o.extra)}</div></div>`:'<p class="muted">Không có nội dung đính kèm.</p>'}<div class="notice"><b>Ghi chú nội bộ</b><br>${esc(o.note)||'Không có ghi chú.'}</div></section><section class="card pad"><div class="sectionhead"><h2>Chuẩn bị & lịch sử</h2><small>${esc(o.assignee)}</small></div><p class="muted">Chuẩn bị ngày ${date(o.prep)} · Checklist ${o.checks.filter(Boolean).length}/4</p><div class="checks">${CHECKS.map((t,i)=>`<div class="check">${o.checks[i]?'✓':'○'} ${t}</div>`).join('')}</div>${o.hold?`<div class="notice warn">${esc(o.hold)} <button class="text" onclick="resume(${o.id})">Đã xử lý</button></div>`:''}<div class="history">${o.history.map(h=>`<p><b>${esc(h.at)}</b> · ${esc(h.text)}</p>`).join('')}</div></section></div><div class="detail-side"><section class="card pad"><h2>Thanh toán</h2><div class="kv"><span>Tiền sản phẩm</span><b>${fmt(o.price)}</b></div><div class="kv"><span>Phí ship tính khách</span><b>${fmt(o.ship)}</b></div><div class="kv big-total"><span>Tổng đơn</span><b>${fmt(total(o))}</b></div><div class="kv"><span>Đã ghi nhận thanh toán</span><b>${fmt(o.paid)}</b></div><div class="notice"><strong>${o.stage==='cancelled'?'Cần hoàn '+fmt(refundDue(o)):customerDue(o)?'Còn phải thanh toán '+fmt(customerDue(o)):'✓ Đã thanh toán đủ'}</strong></div>${o.stage!=='cancelled'&&customerDue(o)>0?`<button class="primary full" onclick="payDialog(${o.id})">Đánh dấu đã thanh toán</button>`:''}${o.stage==='cancelled'&&refundDue(o)>0?`<button class="full" onclick="payDialog(${o.id},'refund')">Ghi nhận đã hoàn tiền</button>`:''}<small class="explain">Hoàn tất tự động khi đã nhận hoa và đã thanh toán đủ.</small></section><section class="card pad"><h3>Phí ship thực tế</h3><div class="kv"><span>Chi phí vận chuyển</span><b>${o.actual===null?'Chưa chốt':fmt(o.actual)}</b></div>${o.fulfillment!=='pickup'?`<button class="full" onclick="shipDialog(${o.id})">Cập nhật nhanh phí ship</button>`:'<p class="muted">Ghé lấy tại tiệm.</p>'}</section><section class="card pad"><h3>Mốc xử lý</h3><div class="kv"><span>Đã giao / nhận</span><b>${o.deliveredAt?esc(o.deliveredAt):'Chưa ghi nhận'}</b></div><div class="kv"><span>Hoàn tất</span><b>${o.completedAt?esc(o.completedAt):'Chưa đủ điều kiện'}</b></div></section>${!['delivered','cancelled'].includes(o.stage)?`<section class="card pad"><h3>Xử lý khác</h3><div class="row wrap" style="margin-top:14px"><button onclick="holdDialog(${o.id})">Tạm dừng</button>${['pending','confirmed','preparing','ready'].includes(o.stage)?`<button onclick="cancelDialog(${o.id})">Hủy đơn</button>`:''}</div></section>`:''}</div></div>`}
function payDialog(id,kind='paid'){let o=get(id),refund=kind==='refund';form(refund?'Xác nhận đã hoàn tiền':'Đánh dấu đã thanh toán',`<div class="pay-confirm"><small>LM-${id} · ${esc(o.customer)}</small><h2>${refund?'Tiền cần hoàn':'Số tiền còn lại'}</h2><strong>${fmt(refund?refundDue(o):customerDue(o))}</strong></div><div class="checks"><label><input type="checkbox" id="paidconfirm" required>${refund?'Tôi xác nhận đã hoàn đủ tiền cho khách':'Tôi xác nhận đơn này đã được thanh toán đủ'}</label></div><p class="muted">${refund?'Đơn vẫn giữ trạng thái đã hủy.':o.stage==='delivered'?'Đã giao + đã thanh toán → đơn tự chuyển sang hoàn tất.':'Đơn tiếp tục ở bước xử lý hiện tại. Chưa giao thì chưa hoàn tất.'}</p><small class="explain">Đây là cập nhật trạng thái đơn. Không tự tạo phiếu thu hoặc số tiền thực nhận ngân hàng.</small>`,`doPay(${id},'${kind}')`,refund?'Đã hoàn tiền':'Xác nhận đã thanh toán')}
function doPay(id,kind='paid'){let o=get(id);if(!checked('paidconfirm'))return err('Vui lòng xác nhận trước khi cập nhật.');if(kind==='refund'){if(o.stage!=='cancelled'||refundDue(o)<=0)return err('Không có khoản cần hoàn.');o.refunded=o.paid;log(o,'Đã xác nhận hoàn đủ tiền')}else{if(o.stage==='cancelled'||customerDue(o)<=0)return err('Trạng thái thanh toán đã được cập nhật.');o.paid=total(o);log(o,'Đánh dấu đã thanh toán đủ')}detail(id);toast(bucket(o)==='done'?'Đã giao & đã thanh toán → hoàn tất':'Đã cập nhật trạng thái thanh toán')}
function confirmDialog(id){let o=get(id);form('Rà soát & xác nhận đơn',`<div class="notice">LM-${id} · ${esc(o.product)} · ${fmt(total(o))}<br>Người đặt: ${esc(o.customer)} · ${esc(o.channel)}</div><div class="checks">${['Mẫu hoa, giá và nội dung đính kèm đã thống nhất','Lịch hẹn, loại nhận hàng đã thống nhất với người đặt','Có thông tin liên hệ người đặt để bổ sung khi cần'].map((s,i)=>`<label><input type="checkbox" id="confirm${i}" required>${s}</label>`).join('')}</div>${!receiverReady(o)&&o.fulfillment!=='pickup'?'<div class="notice warn">Người nhận còn trống. Vẫn có thể xác nhận và chuẩn bị, bổ sung trước bàn giao.</div>':''}<label class="fieldlabel">Điều kiện chuẩn bị</label><select id="policy"><option>Cho phép chuẩn bị ngay</option><option>Yêu cầu cọc trước khi chuẩn bị</option></select>`,`doConfirm(${id})`,'Xác nhận đơn')}
function doConfirm(id){let o=get(id);if(o.stage!=='pending'||o.hold)return err('Hãy xử lý lý do tạm dừng trước.');if(![0,1,2].every(i=>checked('confirm'+i)))return err('Cần rà soát đủ 3 thông tin.');o.stage='confirmed';o.hold=val('policy').startsWith('Yêu cầu')&&o.paid===0?'Chờ nhận cọc trước khi chuẩn bị':'';log(o,'Xác nhận đơn với người đặt');detail(id)}
function recipientDialog(id){let o=get(id);form('Bổ sung thông tin người nhận',`<p class="muted">Có thể để trống khi lưu. Chỉ cần đầy đủ trước bàn giao với đơn ship.</p><button type="button" style="margin-top:12px" onclick="document.getElementById('r-name').value=get(${id}).customer;document.getElementById('r-phone').value=get(${id}).buyerPhone">Người nhận là người đặt</button><label class="fieldlabel" for="r-name">Tên người nhận</label><input id="r-name" value="${esc(o.recipient)}"><label class="fieldlabel" for="r-phone">Số điện thoại người nhận</label><input id="r-phone" type="tel" value="${esc(o.recipientPhone)}"><label class="fieldlabel" for="r-address">Địa chỉ nhận</label><textarea id="r-address">${esc(o.address)}</textarea>`,`saveRecipient(${id})`)}
function saveRecipient(id){let o=get(id);o.recipient=val('r-name').trim();o.recipientPhone=val('r-phone').trim();o.address=val('r-address').trim();log(o,'Cập nhật thông tin người nhận');closeModal();toast('Đã lưu thông tin người nhận')}
function dispatchDialog(id){let o=get(id);if(!receiverReady(o))return modal('Bổ sung thông tin trước khi bàn giao',`<div class="notice warn">Cần tên, số điện thoại và địa chỉ người nhận cho đơn ${FULFILL[o.fulfillment].toLowerCase()}.</div><div class="modalfoot"><button onclick="closeModal()">Để sau</button><button class="primary" onclick="recipientDialog(${id})">Bổ sung ngay</button></div>`);form('Bàn giao cho shipper',`<div class="notice">LM-${id} · ${esc(o.recipient)} · ${esc(o.recipientPhone)}<br>${esc(o.address)}</div><label class="fieldlabel">Thông tin giao nhận</label><input id="carrier" placeholder="Tên shipper / đơn vị vận chuyển" required>${shippingFields(o)}<div class="checks"><label><input type="checkbox" id="handover" required>Đã bàn giao hoa và thông tin người nhận</label></div>`,`doDispatch(${id})`,'Xác nhận đang giao')}
function doDispatch(id){let o=get(id),cost=parseCost();if(o.stage!=='ready'||o.hold||!receiverReady(o))return err('Cần sẵn sàng giao và đầy đủ thông tin nhận.');if(!val('carrier').trim()||!checked('handover'))return err('Cần thông tin và xác nhận bàn giao.');if(cost!==null&&(!Number.isInteger(cost)||cost<0))return err('Phí không hợp lệ.');o.actual=cost;o.carrier=val('carrier').trim();o.stage='delivering';log(o,'Bàn giao · '+o.carrier);detail(id)}
function deliveredDialog(id){let o=get(id),pickup=o.fulfillment==='pickup';form(pickup?'Xác nhận khách đã nhận tại tiệm':'Xác nhận giao thành công',`<div class="notice">LM-${id} · ${esc(o.product)}<br>${moneyState(o)}</div>${pickup?'':shippingFields(o)}<div class="checks"><label><input type="checkbox" id="received" required>${pickup?'Khách đã nhận hoa tại tiệm':'Người nhận đã nhận hoa thành công'}</label></div><small>Ghi nhận ở thời điểm mô phỏng 12/10/2026 10:30. Thanh toán được cập nhật riêng.</small>${pickup?'':`<div style="margin-top:15px"><button type="button" onclick="failDialog(${id})">Giao chưa thành công</button></div>`}`,`doDelivered(${id})`,pickup?'Khách đã nhận hoa':'Ghi nhận đã giao')}
function doDelivered(id){let o=get(id),pickup=o.fulfillment==='pickup',cost=pickup?0:parseCost();if((pickup?o.stage!=='ready':o.stage!=='delivering')||o.hold)return err('Đơn chưa ở bước nhận / giao hàng.');if(!checked('received'))return err('Cần xác nhận đã nhận hoa.');if(cost!==null&&(!Number.isInteger(cost)||cost<0))return err('Phí không hợp lệ.');o.actual=cost;o.stage='delivered';o.deliveredAt=TODAY+' 10:30';log(o,pickup?'Khách đã nhận tại tiệm':'Giao hàng thành công');detail(id)}
function saveShip(id){let o=get(id),n=parseCost();if(n!==null&&(!Number.isInteger(n)||n<0))return err('Phí phải là số nguyên không âm.');o.actual=n;log(o,'Phí ship thực tế: '+(n===null?'chưa chốt':fmt(n)));detail(id)}
function cancelDialog(id){form('Hủy đơn trước khi giao',`<div class="notice warn">Khoản đã thanh toán được giữ lại để theo dõi hoàn tiền ngay trong chi tiết đơn. Đơn hủy không tính hoàn tất.</div><label class="fieldlabel">Lý do hủy</label><textarea id="cancelreason" required></textarea>`,`doCancel(${id})`,'Xác nhận hủy đơn')}
function freshDraft(){return {name:'',phone:'',channel:'Facebook',product:'',qty:1,price:'',fulfillment:'city',date:TODAY,time:'15:00',recipient:'',recipientPhone:'',address:'',extraType:'Không',extra:'',note:'',ship:35000,paid:0,fullpaid:false}}
function openCreate(){closeModal();if(!draft)draft=freshDraft();go('create')}
function field(label,id,value,attrs=''){return `<label class="fieldlabel" for="${id}">${label}</label><input id="${id}" value="${esc(value)}" ${attrs}>`}
function options(values,current){return values.map(v=>`<option ${v===current?'selected':''}>${esc(v)}</option>`).join('')}
function createPage(){let d=draft||freshDraft();return `<button class="text back-link" onclick="go('orders')">← Quay lại đơn hàng</button>`+heading('ĐƠN HÀNG / TẠO MỚI','Bắt đầu từ người đặt.','Lưu đơn ngay cả khi chưa có thông tin người nhận. Bạn có thể bổ sung sau.',`<button onclick="go('orders')">Để sau</button><button class="primary" type="submit" form="create-order">Tạo đơn hàng</button>`)+`<form id="create-order" onsubmit="event.preventDefault();createOrder()" oninput="captureDraft();updateDraftTotals()" onchange="captureDraft();updateDraftTotals()"><div class="create-layout"><div class="detail-main"><section class="card pad"><div class="sectionhead"><div class="row"><span class="section-number">01</span><div><h2>Thông tin người đặt</h2><p>Thông tin ưu tiên để liên hệ và xác nhận đơn</p></div></div><span class="badge">Bắt buộc</span></div><div class="form-grid"><div>${field('Tên người đặt *','n-name',d.name,'required autocomplete="name" placeholder="Tên người đặt hoa"')}</div><div>${field('Số điện thoại người đặt *','n-phone',d.phone,'required type="tel" autocomplete="tel" placeholder="Số liên hệ người đặt"')}</div><div class="span2"><label class="fieldlabel" for="n-channel">Kênh đặt hàng *</label><select id="n-channel">${options(['Facebook','Instagram','Zalo','Website','Tại tiệm','Điện thoại','Khác'],d.channel)}</select></div></div></section><section class="card pad"><div class="sectionhead"><div class="row"><span class="section-number">02</span><h2>Sản phẩm & lịch hẹn</h2></div></div><div class="form-grid"><div class="span2">${field('Tên sản phẩm / mẫu hoa *','n-product',d.product,'required placeholder="VD: Bó hồng Ohara tone hồng"')}</div><div>${field('Số lượng *','n-qty',d.qty,'type="number" min="1" step="1" required')}</div><div>${field('Đơn giá (đ) *','n-price',d.price,'type="number" min="1" step="1" required placeholder="850000"')}</div><div>${field('Ngày nhận / giao *','n-date',d.date,`type="date" min="${TODAY}" required`)}</div><div>${field('Giờ hẹn *','n-time',d.time,'type="time" required')}</div></div><label class="fieldlabel" for="n-fulfillment">Loại nhận hàng *</label><select id="n-fulfillment">${Object.entries(FULFILL).map(([k,v])=>`<option value="${k}" ${k===d.fulfillment?'selected':''}>${v}</option>`).join('')}</select></section><section class="card pad"><div class="sectionhead"><div class="row"><span class="section-number">03</span><div><h2>Thông tin người nhận</h2><p>Có thể để trống và bổ sung sau</p></div></div><span class="badge upcoming">Không bắt buộc</span></div><button type="button" onclick="copyBuyer()">Người nhận là người đặt</button><div class="form-grid"><div>${field('Tên người nhận','n-recipient',d.recipient,'placeholder="Chưa có cũng được"')}</div><div>${field('Số điện thoại người nhận','n-recipientPhone',d.recipientPhone,'type="tel" placeholder="Bổ sung sau"')}</div><div class="span2"><label class="fieldlabel" for="n-address">Địa chỉ nhận</label><textarea id="n-address" placeholder="Bổ sung trước khi bàn giao nếu chọn ship">${esc(d.address)}</textarea></div></div><div class="notice" id="receiver-note">Không tự sao chép người đặt sang người nhận. Chỉ sao chép khi bạn bấm nút phía trên.</div></section><section class="card pad"><div class="sectionhead"><div class="row"><span class="section-number">04</span><h2>Nội dung thêm</h2></div></div><label class="fieldlabel" for="n-extraType">Thiệp / banner</label><select id="n-extraType">${options(['Không','Thiệp','Banner','Thiệp & Banner'],d.extraType)}</select><div id="extra-field" ${d.extraType==='Không'?'hidden':''}><label class="fieldlabel" for="n-extra">Nội dung cần in</label><textarea rows="4" id="n-extra" placeholder="Nhập chính xác lời chúc, tên người gửi…">${esc(d.extra)}</textarea></div><label class="fieldlabel" for="n-note">Ghi chú nội bộ</label><textarea id="n-note" placeholder="Yêu cầu về hoa, giấy gói, lưu ý khi giao…">${esc(d.note)}</textarea></section></div><aside class="create-summary card pad"><h2>Tóm tắt đơn mới</h2><p class="bottomnote">Chờ xác nhận sau khi tạo</p><div class="kv"><span>Tiền sản phẩm</span><b id="draft-products">${fmt(Number(d.qty)*Number(d.price))}</b></div>${field('Phí ship tính khách (đ)','n-ship',d.ship,'type="number" min="0" step="1"')}<div class="kv big-total"><span>Tổng đơn</span><b id="draft-total">${fmt(Number(d.qty)*Number(d.price)+Number(d.ship))}</b></div><label class="fieldlabel" for="n-paid">Số tiền đã thanh toán / cọc (đ)</label><input id="n-paid" type="number" min="0" step="1" value="${d.paid}"><label class="check" style="margin:15px 0"><input type="checkbox" id="n-fullpaid" ${d.fullpaid?'checked':''}>Đã thanh toán đủ</label><div id="draft-status" class="notice">Còn phải thanh toán: ${fmt(Math.max(0,Number(d.qty)*Number(d.price)+Number(d.ship)-Number(d.paid)))}</div><p id="create-error" role="alert"></p><button class="primary full" type="submit">Tạo đơn hàng</button><small class="explain">Người nhận có thể để trống. Dữ liệu mẫu chỉ lưu trên trình duyệt này.</small></aside></div></form>`}
function captureDraft(){if(page!=='create')return;draft={name:val('n-name'),phone:val('n-phone'),channel:val('n-channel'),product:val('n-product'),qty:Number(val('n-qty')),price:val('n-price'),fulfillment:val('n-fulfillment'),date:val('n-date'),time:val('n-time'),recipient:val('n-recipient'),recipientPhone:val('n-recipientPhone'),address:val('n-address'),extraType:val('n-extraType'),extra:val('n-extra'),note:val('n-note'),ship:Number(val('n-ship')),paid:Number(val('n-paid')),fullpaid:checked('n-fullpaid')};if(draft.fulfillment==='pickup')draft.ship=0;if(draft.fullpaid)draft.paid=Number(draft.qty)*Number(draft.price)+draft.ship}
function updateDraftTotals(){let d=draft;if(!d)return;let products=Number(d.qty)*Number(d.price),sum=products+Number(d.ship);document.getElementById('draft-products').textContent=fmt(products);document.getElementById('draft-total').textContent=fmt(sum);document.getElementById('n-ship').value=d.ship;document.getElementById('n-ship').disabled=d.fulfillment==='pickup';document.getElementById('n-paid').value=d.paid;document.getElementById('n-paid').disabled=d.fullpaid;document.getElementById('n-paid').max=sum;document.getElementById('draft-status').textContent=d.paid>sum?'Số tiền đã thanh toán không được vượt tổng đơn':d.paid===sum&&sum>0?'✓ Đã thanh toán đủ':'Còn phải thanh toán: '+fmt(Math.max(0,sum-d.paid));document.getElementById('extra-field').hidden=d.extraType==='Không';document.getElementById('n-extra').required=d.extraType!=='Không';document.getElementById('receiver-note').textContent=d.fulfillment==='pickup'?'Ghé lấy tại tiệm: không bắt buộc người nhận và địa chỉ.':'Thông tin người nhận có thể bổ sung sau, trước khi bàn giao đơn ship.'}
function copyBuyer(){document.getElementById('n-recipient').value=val('n-name');document.getElementById('n-recipientPhone').value=val('n-phone');captureDraft();toast('Đã sao chép tên và số điện thoại người đặt')}
function createOrder(){captureDraft();let d=draft,error=document.getElementById('create-error');if(!d.name.trim()||!d.phone.trim()||!d.product.trim()){error.textContent='Cần tên, số điện thoại người đặt và sản phẩm.';return}let price=Number(d.price),sum=price*d.qty+d.ship;if(!Number.isInteger(price)||price<=0||!Number.isInteger(d.qty)||d.qty<=0||!Number.isInteger(d.ship)||d.ship<0||!Number.isInteger(d.paid)||d.paid<0||d.paid>sum){error.textContent='Kiểm tra số lượng, giá, phí ship và khoản đã thanh toán.';return}if(!d.date||d.date<TODAY||!d.time){error.textContent='Vui lòng chọn lịch hẹn hợp lệ.';return}if(d.extraType!=='Không'&&!d.extra.trim()){error.textContent='Vui lòng nhập nội dung thiệp / banner hoặc chọn Không.';return}let id=Math.max(...db.map(o=>o.id))+1;db.push({id,customer:d.name.trim(),buyerPhone:d.phone.trim(),channel:d.channel,product:d.product.trim(),qty:d.qty,unitPrice:price,price:price*d.qty,ship:d.ship,paid:d.paid,actual:d.fulfillment==='pickup'?0:null,fulfillment:d.fulfillment,recipient:d.recipient.trim(),recipientPhone:d.recipientPhone.trim(),address:d.address.trim(),extraType:d.extraType,extra:d.extraType==='Không'?'':d.extra.trim(),note:d.note.trim(),date:d.date,time:d.time,prep:d.date,stage:'pending',hold:'',assignee:'Chưa phân công',checks:[false,false,false,false],refunded:0,createdAt:'12/10/2026 · 10:30',deliveredAt:null,completedAt:null,history:[{at:'12/10 · 10:30',text:'Tạo đơn · Chờ xác nhận'+(!d.recipient.trim()?' · Người nhận chưa cung cấp':'')}]});save();draft=null;selectedOrder=id;page='detail';render();window.scrollTo({top:0,behavior:'instant'});toast('Đã tạo LM-'+id+' · Chờ xác nhận')}
function resetDialog(){modal('Khôi phục dữ liệu mẫu?','<p class="muted">Xóa thao tác thử và các đơn đã tạo trong bản mẫu này.</p><div class="modalfoot"><button onclick="closeModal()">Giữ nguyên</button><button class="primary" onclick="db=seed();draft=null;save();closeModal();go(\'orders\');toast(\'Đã khôi phục mẫu\')">Khôi phục</button></div>')}
function guide(){modal('Các màn hình đã điều chỉnh',`<table class="guide-table"><thead><tr><th>Màn hình</th><th>Thay đổi</th></tr></thead><tbody><tr><td>Lưới đơn hàng</td><td>Xem người đặt, điện thoại, kênh đặt, cách nhận, trạng thái và tiền còn lại, thiệp / banner ngay trên dòng.</td></tr><tr><td>Xem tóm tắt</td><td>Modal gọn: thông tin chính và thao tác xác nhận, chuẩn bị, thanh toán, giao hàng, phí ship.</td></tr><tr><td>Xem chi tiết</td><td>Trang riêng: người đặt, người nhận, sản phẩm, lịch hẹn, nội dung thêm, thanh toán và lịch sử đầy đủ.</td></tr><tr><td>Tạo đơn</td><td>Thông tin người đặt ở đầu, người nhận tùy chọn. Sao chép người đặt sang người nhận chỉ khi chủ động bấm.</td></tr><tr><td>Thanh toán</td><td>Đã thanh toán / Chưa thanh toán đủ, kèm số tiền còn lại. Cập nhật ngay từ đơn hàng, không có menu thanh toán riêng.</td></tr></tbody></table><div class="notice">Chờ xác nhận → Đã xác nhận → Đang chuẩn bị → Sẵn sàng → Đang giao → Đã giao.<br>Ghé lấy: Sẵn sàng nhận → Khách đã nhận tại tiệm, bỏ qua bước vận chuyển.<br><strong>Hoàn tất = Đã giao / nhận hoa + Đã thanh toán đủ.</strong></div><p class="bottomnote">Người nhận trống không chặn tạo, xác nhận hoặc chuẩn bị. Đơn ship cần tên, số liên hệ và địa chỉ trước khi bàn giao. Trạng thái thanh toán không tự sinh phiếu thu hay thay thế dữ liệu dòng tiền thực tế.</p><div class="notice">Thử nút “Tạo đơn hàng”: nhập người đặt, để trống người nhận rồi lưu.<br>Trên lưới, so sánh “Xem tóm tắt” với “Xem chi tiết”. Bấm biểu tượng thiệp để xem nội dung.<br>LM-307 còn 740.000đ: đánh dấu đã thanh toán → tự hoàn tất.</div>`,'LAMIE / THIẾT KẾ MỚI')}
render();

